namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious traditional Italian pizza.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a creamy spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Cumin", "Tomato sauce", "Heavy cream", "Garlic", "Ginger", "Onion"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and cumin for at least 1 hour.",
                    "Grill or broil chicken until charred and cooked through. Cut into pieces.",
                    "Sauté diced onion, garlic, and ginger in oil until softened.",
                    "Add tomato sauce and spices; simmer for 15 minutes.",
                    "Stir in heavy cream and add the cooked chicken.",
                    "Simmer for 10 minutes and serve over basmati rice."
                ],
                TotalRatings = 8, RatingSum = 37
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Classic Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and plenty of black pepper.",
                    "Drain pasta, reserving 1 cup of pasta water.",
                    "Toss hot pasta with pancetta, then remove from heat.",
                    "Quickly stir in the egg mixture, adding pasta water to create a creamy sauce."
                ],
                TotalRatings = 15, RatingSum = 68
            },
            new Recipe
            {
                Id = 4, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm taco shells in the oven for 3 minutes.",
                    "Fill shells with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, and sour cream."
                ],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Asian",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Sugar"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes; drain.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry shrimp in a hot wok until pink; set aside.",
                    "Scramble eggs in the wok, then add noodles and sauce.",
                    "Toss in shrimp, bean sprouts, and green onions.",
                    "Serve with crushed peanuts and lime wedges."
                ],
                TotalRatings = 6, RatingSum = 26
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit avocados; scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in diced onion, jalapeño, tomato, and cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                TotalRatings = 20, RatingSum = 90
            },
            new Recipe
            {
                Id = 7, Title = "Vegetable Stir-Fry", Category = "Asian",
                Description = "Quick and colorful veggie stir-fry with soy-ginger sauce.",
                Ingredients = ["Broccoli", "Bell peppers", "Carrots", "Snap peas", "Soy sauce", "Ginger", "Garlic", "Sesame oil", "Rice"],
                Steps = [
                    "Cook rice according to package directions.",
                    "Mix soy sauce, minced ginger, garlic, and sesame oil for the sauce.",
                    "Heat oil in a wok over high heat.",
                    "Add vegetables in order of firmness; stir-fry for 5–7 minutes.",
                    "Pour sauce over vegetables and toss to coat.",
                    "Serve over steamed rice."
                ],
                TotalRatings = 4, RatingSum = 16
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Soft and chewy homemade chocolate chip cookies.",
                Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla extract", "Flour", "Baking soda", "Salt", "Chocolate chips"],
                Steps = [
                    "Preheat oven to 375°F (190°C).",
                    "Cream butter with both sugars until fluffy.",
                    "Beat in eggs and vanilla extract.",
                    "Mix in flour, baking soda, and salt until just combined.",
                    "Fold in chocolate chips.",
                    "Drop rounded tablespoons onto baking sheets.",
                    "Bake for 9–11 minutes until golden brown. Cool on a wire rack."
                ],
                TotalRatings = 25, RatingSum = 118
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

