@page "/"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">🍽️ RecipeShare</h1>
    <p class="lead text-muted">Discover, share, and rate delicious recipes from around the world.</p>
</div>

<h2 class="mb-3">Browse by Category</h2>

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col">
            <a href="category/@Uri.EscapeDataString(category)" class="text-decoration-none">
                <div class="card h-100 shadow-sm border-0 category-card">
                    <div class="card-body text-center py-5">
                        <h3 class="card-title mb-2">@GetCategoryEmoji(category) @category</h3>
                        <p class="card-text text-muted">
                            @RecipeService.GetByCategory(category).Count recipe(s)
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-5">
    <a href="submit" class="btn btn-success btn-lg">📝 Submit Your Recipe</a>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Mexican" => "🇲🇽",
        "Asian" => "🥢",
        "Desserts" => "🍰",
        _ => "🍴"
    };
}

arguments.file_text:
@page "/category/{CategoryName}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in Recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">
                            <a href="recipe/@recipe.Id">@recipe.Title</a>
                        </h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                            }
                            <span class="text-muted ms-1">(@recipe.AverageRating.ToString("0.0"))</span>
                        </div>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeShare.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@Uri.EscapeDataString(Recipe.Category)">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="lead text-muted">@Recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><strong>🥘 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>📋 Instructions</h4>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-3">
        <div class="card-body">
            <h5 class="card-title">Rate this Recipe</h5>
            <StarRating RecipeId="Recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <div class="star-rating" role="group" aria-label="Rate this recipe">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                    class="btn btn-link text-decoration-none p-0 fs-3 @(star <= (HoverRating ?? SelectedRating) ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    @onmouseover="() => HoverRating = star"
                    @onmouseout="() => HoverRating = null"
                    disabled="@Submitted"
                    aria-label="@star stars">
                @(star <= (HoverRating ?? SelectedRating) ? "★" : "☆")
            </button>
        }
    </div>

    @if (Submitted)
    {
        <span class="badge bg-success">Thanks! You rated @SelectedRating star(s).</span>
    }

    @if (Recipe is not null)
    {
        <span class="text-muted ms-2">
            Avg: @Recipe.AverageRating.ToString("0.0") (@Recipe.TotalRatings ratings)
        </span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private int? HoverRating { get; set; }
    private bool Submitted { get; set; }
    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (Submitted) return;
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetById(RecipeId);
        Submitted = true;
    }
}

