    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <div class="star-rating" role="group" aria-label="Rate this recipe">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                    class="btn btn-link text-decoration-none p-0 fs-3 @(star <= (HoverRating ?? SelectedRating) ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    @onmouseover="() => HoverRating = star"
                    @onmouseout="() => HoverRating = null"
                    disabled="@Submitted"
                    aria-label="@star stars">
                @(star <= (HoverRating ?? SelectedRating) ? "★" : "☆")
            </button>
        }
    </div>

    @if (Submitted)
    {
        <span class="badge bg-success">Thanks! You rated @SelectedRating star(s).</span>
    }

    @if (Recipe is not null)
    {
        <span class="text-muted ms-2">
            Avg: @Recipe.AverageRating.ToString("0.0") (@Recipe.TotalRatings ratings)
        </span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private int? HoverRating { get; set; }
    private bool Submitted { get; set; }
    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (Submitted) return;
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetById(RecipeId);
        Submitted = true;
    }
}

